package app

import (
	"context"
	"os"
	"path/filepath"
	"sort"

	"github.com/nxsky/twill/runtime/infra"
	"github.com/nxsky/twill/runtime/tool"
)

func infraCommand() *tool.Command {
	flags, compact, dir := inspectFlagSet("infra")
	terraform := flags.Bool("terraform", false, "Include Terraform resource blocks in the output")
	output := flags.String("output", "", "Write generated Terraform files under this directory")

	return &tool.Command{
		Name:        "infra",
		Flags:       flags,
		Description: "Generate an infrastructure plan from resource declarations",
		Help: `Usage:
  twill app infra [--dir DIR] [--terraform] [--output DIR] [packages...]

Description:
  "twill app infra" scans safe resource metadata and emits a structured
  infrastructure plan covering local provisioning, Kubernetes provisioning,
  and cloud resource requirements. The plan includes per-resource specs for
  Docker Compose, Helm charts, and cloud-managed services. Pass --terraform
  to include Terraform resource blocks in the output. Pass --output to write
  generated Terraform files under that directory.

  If no packages are provided, the current package is inspected. Package
  patterns follow the same syntax as go list, for example:

    twill app infra ./...
    twill app infra --terraform ./...
    twill app infra --terraform --output ./terraform ./...

Flags:
` + tool.FlagsHelp(flags),
		Fn: func(ctx context.Context, args []string) error {
			resources, err := InspectResourcesContext(ctx, GraphOptions{
				Dir:      *dir,
				Patterns: args,
			})
			if err != nil {
				return err
			}

			plan := buildInfraPlan(resources)

			if *terraform {
				blocks := infra.GenerateTerraform(plan)
				plan.Limitations = append(plan.Limitations,
					"Terraform blocks are templates; review provider configuration and state management before use.")
				if *output != "" {
					if err := writeTerraformFiles(blocks, *output); err != nil {
						return err
					}
				}
			}

			return encodeJSON(os.Stdout, plan, !*compact, "infra")
		},
	}
}

func buildInfraPlan(resources ResourcesContext) infra.InfraPlan {
	// Group resources by component
	compMap := map[string][]infra.ResourceInput{}
	for _, res := range resources.Resources {
		comp := res.Component
		if comp == "" {
			comp = "default"
		}
		compMap[comp] = append(compMap[comp], infra.ResourceInput{
			Name:      res.Name,
			Kind:      res.Kind,
			Type:      res.Type,
			Component: comp,
		})
	}

	var components []infra.ComponentInput
	for comp, resList := range compMap {
		components = append(components, infra.ComponentInput{
			Name:      comp,
			Resources: resList,
		})
	}
	sort.Slice(components, func(i, j int) bool {
		return components[i].Name < components[j].Name
	})

	return infra.GeneratePlan(infra.GraphInput{
		ApplicationName: "twill-app",
		Components:      components,
	})
}

func writeTerraformFiles(blocks []infra.TerraformBlock, outDir string) error {
	if err := os.MkdirAll(outDir, 0o755); err != nil {
		return err
	}
	content := "# Generated by twill app infra --terraform\n# Review and customize before production use.\n\n"
	content += infra.RenderTerraform(blocks)
	return os.WriteFile(filepath.Join(outDir, "main.tf"), []byte(content), 0o644)
}
